  body.add(mk(GEO.sphHi, grey, 9, 8, 14, 0, -1, 40));                                                            // snute
  const fin = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 3), dark); fin.scale.set(3, 26, 13); fin.position.set(0, 20, -2); fin.rotation.x = -0.35; fin.castShadow = true; body.add(fin);   // ryggfinnen
  for (const sx of [-1, 1]) { const pf = mk(GEO.sphHi, dark, 14, 1.6, 6, sx * 14, -7, 12); pf.rotation.set(0, sx * .5, sx * .45); body.add(pf); }   // sidefinner
  for (const sx of [-1, 1]) body.add(mk(GEO.sph, M.black, 1.8, 1.8, 1.4, sx * 7.2, 3, 36, false));
  body.add(mk(GEO.box, M.black, 12, 1, 6, 0, -6, 41, false));                                                    // munnen
  for (let i = -4; i <= 4; i++) { const t2 = mk(GEO.cone, M.white, .9, 2.6, .9, i * 1.3, -5, 43.6 - Math.abs(i) * .4, false); t2.rotation.x = Math.PI; body.add(t2); }
  for (let i = 0; i < 4; i++) for (const sx of [-1, 1]) body.add(mk(GEO.box, dark, .4, 5, 1, sx * 11, 1, 22 - i * 3, false));   // gjellespalter
  const tail = new THREE.Group(); tail.position.set(0, 0, -42); body.add(tail);
  tail.add(mk(GEO.sphHi, grey, 6, 6, 16, 0, 0, -8));
  const t1 = mk(GEO.cone, dark, 2, 26, 9, 0, 12, -18); t1.rotation.x = -0.6; tail.add(t1);
  const t2 = mk(GEO.cone, dark, 2, 18, 7, 0, -8, -16); t2.rotation.x = Math.PI + 0.7; tail.add(t2);
