  const head = new THREE.Group(); head.position.y = 25; torso.add(head);
  head.add(mk(GEO.cyl, skin, 3, 4, 3, 0, 1.5, 0), mk(GEO.sphHi, skin, 7, 8, 7, 0, 9, 0));
