  const wt = new THREE.Group(); wt.position.set(-60, 0, 330); G.add(wt);
  for (const [x, z] of [[-14, -14], [14, -14], [-14, 14], [14, 14]]) wt.add(mk(GEO.box, m.woodD, 3, 60, 3, x, 30, z));
  wt.add(mk(GEO.cyl, m.plankA, 22, 30, 22, 0, 75, 0), mk(GEO.cone, m.roof, 25, 14, 25, 0, 97, 0));
  for (const [x, z] of [[-55, -100], [-58, -90], [55, 40], [52, 200], [-55, 180]]) box(m.wood, 9, 12, 9, x, 6, z);
  for (const [x, z] of [[-52, 60], [56, -60]]) { box(m.woodD, 2, 14, 2, x, 7, z - 20); box(m.woodD, 2, 14, 2, x, 7, z + 20); box(m.woodD, 2, 2, 42, x, 13, z); }
  const horses = [];
  for (const [x, z, r] of [[-66, 60, Math.PI / 2], [68, -60, -Math.PI / 2], [150, 60, 0]]) { const hz = makeAnimal({ type: 'villhest', x: 0, y: 0 }); hz.grp.position.set(x * TOWN_K, 0, z * TOWN_K); hz.grp.rotation.y = r; OUT.add(hz.grp); horses.push(hz); }
  for (let k = 0; k < 10; k++) { const a = k / 10 * 6.28 + .2, r2 = 360 + (k % 3) * 40; if (trackDist(TOWNX + Math.cos(a) * r2 * TOWN_K, TOWNY + TOWN_OY + (Math.sin(a) * r2 + 40) * TOWN_K) < 110) continue; const c = new THREE.Group(); c.position.set(Math.cos(a) * r2, 0, Math.sin(a) * r2 + 40); G.add(c); const h3 = 26 + (k % 4) * 6; c.add(mk(GEO.cyl, m.cactus, 4, h3, 4, 0, h3 / 2, 0), mk(GEO.sphHi, m.cactus, 4, 3, 4, 0, h3, 0)); if (k % 2) c.add(mk(GEO.cyl, m.cactus, 2.6, 12, 2.6, 7, h3 * .55, 0)); }
  { const sg = new THREE.Group(); sg.position.set(-70, 0, -250); G.add(sg); sg.add(mk(GEO.cyl, m.woodD, 2, 40, 2, -26, 20, 0), mk(GEO.cyl, m.woodD, 2, 40, 2, 26, 20, 0), mk(GEO.box, m.signs.town, 60, 14, 2, 0, 36, 0)); }
  // figurer
  const npcs = TOWN_NPCS.map(n => { const f = makeCowboy({ col: n.col, hat: n.hat, star: n.star, mustache: n.id === 'sheriff' ? '#5a3a1a' : n.id === 'cowboy' ? '#8a5a2a' : null, pants: n.id === 'saloon' ? '#5a2a3a' : undefined, vest: n.vest }); f.position.set(n.x * TOWN_K, 0, n.y * TOWN_K); f.rotation.y = n.x < 0 ? Math.PI / 2 : -Math.PI / 2; OUT.add(f); return f; });
