if (world && (typeof world.seed !== 'number' || !isFinite(world.seed))) world = null;
if (world) world.buildings = Array.isArray(world.buildings) ? world.buildings.filter(b => b && typeof b.type === 'string' && isFinite(b.x) && isFinite(b.y)) : [];
