  { const off = o => !townNear(o.x, o.y, 520); g.trees = g.trees.filter(off); g.rocks = g.rocks.filter(off); g.bushes = g.bushes.filter(off); g.tufts = g.tufts.filter(off); }   // plass til den store byen
