  if (t.k === 'tree') { burst(o.x, o.y - 12, '#d9b07a', 8); burst(o.x, o.y - 40, '#5f9e45', 6); sfx('tree'); }
  else if (t.k === 'rock') { burst(o.x, o.y - 10, o.ore ? '#e08a4a' : '#d6d9d4', 8); burst(o.x, o.y - 12, '#fff6c0', 4); g.shake = Math.max(g.shake, 0.05); sfx('rock'); }
