const lam = (c, o = {}) => new THREE.MeshPhongMaterial(Object.assign({ color: c, shininess: 4, specular: 0x111111 }, o));
const basic = (c, o = {}) => new THREE.MeshBasicMaterial(Object.assign({ color: c }, o));
function mk(geo, mat, sx, sy, sz, x = 0, y = 0, z = 0, shadow = true) {
  const m = new THREE.Mesh(geo, mat); m.scale.set(sx, sy, sz); m.position.set(x, y, z); m.castShadow = shadow; return m;
}
function cone(mat, r, h, x, y, z, rx = Math.PI / 2) { const c = mk(GEO.cone, mat, r, h, r, x, y, z); c.rotation.x = rx; return c; }
// Høyden på bakken: bakker og daler, men flatt rundt bålet og nede ved bekken
