function groundTexture() {
  const N = 2048, k = N / W, c = document.createElement('canvas'); c.width = c.height = N;
  const x = c.getContext('2d');
  // Grunnfarge for hvert biom, blandet mykt ved grensene
  const S = 256, sm = document.createElement('canvas'); sm.width = sm.height = S;
  const sx = sm.getContext('2d'), img = sx.createImageData(S, S);
  const COL = { skog: [58, 92, 48], sno: [230, 237, 242], jungel: [40, 86, 34], lava: [42, 34, 32], orken: [214, 184, 124] };
  for (let j = 0; j < S; j++) for (let i = 0; i < S; i++) {
    const w = biomeW((i + .5) / S * W, (j + .5) / S * H), o = (j * S + i) * 4;
    for (let ch = 0; ch < 3; ch++) img.data[o + ch] = COL.skog[ch] * w.skog + COL.sno[ch] * w.sno + COL.jungel[ch] * w.jungel + COL.lava[ch] * w.lava + COL.orken[ch] * w.orken;
    img.data[o + 3] = 255;
  }
  sx.putImageData(img, 0, 0);
  x.imageSmoothingEnabled = true; x.drawImage(sm, 0, 0, N, N);
  for (const pa of g.patches) { x.fillStyle = pa.c; x.beginPath(); x.arc(pa.x * k, pa.y * k, pa.r * k, 0, 7); x.fill(); }
  for (let i = 0; i < 90000; i++) {
    const px = Math.random() * N, py = Math.random() * N, b = biomeAt(px / k, py / k);
    x.fillStyle = b === 'sno' ? (Math.random() < .5 ? 'rgba(180,200,220,.5)' : 'rgba(255,255,255,.7)')
               : b === 'lava' ? (Math.random() < .5 ? 'rgba(20,14,12,.6)' : 'rgba(90,60,50,.4)')
               : b === 'jungel' ? (Math.random() < .5 ? 'rgba(70,120,40,.45)' : 'rgba(15,40,12,.45)')
               : b === 'orken' ? (Math.random() < .5 ? 'rgba(240,215,160,.45)' : 'rgba(170,135,80,.35)')
               : (Math.random() < .5 ? 'rgba(90,130,64,.45)' : 'rgba(22,40,18,.4)');
    x.fillRect(px, py, 2, 3);
  }
  // Glødende sprekker i lavaverdenen
  x.lineWidth = 1.5; x.strokeStyle = 'rgba(255,110,30,.55)';
  for (let i = 0; i < 700; i++) {
    let px = rand(0, W), py = rand(0, H); if (biomeW(px, py).lava < .8) continue;
    x.beginPath(); x.moveTo(px * k, py * k);
    for (let s2 = 0; s2 < 5; s2++) { px += rand(-25, 25); py += rand(-25, 25); x.lineTo(px * k, py * k); }
    x.stroke();
  }
  for (const l of g.lavaPools) { x.fillStyle = '#1a1210'; x.beginPath(); x.arc(l.x * k, l.y * k, (l.r + 14) * k, 0, 7); x.fill(); }
  x.fillStyle = '#5a4630'; x.beginPath(); x.arc(FX * k, FY * k, 85 * k, 0, 7); x.fill();
  for (const t of g.tufts) if (t.k === 1) { x.fillStyle = t.j ? (Math.random() < .5 ? '#ff6fa8' : '#ffd23f') : (Math.random() < .5 ? '#f1ecd8' : '#f4d35e'); x.fillRect(t.x * k, t.y * k, 3, 3); }
  const tex = new THREE.CanvasTexture(c); tex.anisotropy = R3.renderer.capabilities.getMaxAnisotropy();
  return tex;
}
