    // er −y bevegelsesretningen, så eggen treffer først. Nakken (den butte baksiden) peker mot +y.
    const axeG = new THREE.Group(); axe.add(axeG); axe.userData.axeG = axeG;
    axeG.add(mk(GEO.box, M.handle, 2.6, 2.6, 26, 0, 0, 10));
