    { const loop = mk(GEO.box, dark, 1.6, 1.6, 9, 0, 9, 12); saw.add(loop, mk(GEO.box, dark, 1.6, 6, 1.6, 0, 6, 16.5)); }                   // fremre bøyle
    saw.add(mk(GEO.box, alu, 1, 4.4, 26, 0, -0.5, 28), mk(GEO.box, dark, 1.4, 5.4, 27, 0, -0.5, 28.2));   // sverd og kjede
