  const rubberT = cTex(128, 128, (x, w, h) => { x.fillStyle = '#f2f1ec'; x.fillRect(0, 0, w, h); for (let j = 0; j < h; j += 8) { x.fillStyle = 'rgba(0,0,0,.06)'; x.fillRect(0, j, w, 2); } grain(x, w, h, 500, .05); }, [2, 2]);
  const blond = [new THREE.Color('#f0d27a'), new THREE.Color('#f8e4a4'), new THREE.Color('#e4c165'), new THREE.Color('#d6b157')];
