    blond,
    torsoMat: heroMat({ map: torsoT, bumpMap: torsoT, bumpScale: .015, roughness: .95 }),
    hoodie: sleeve, hoodieD: heroMat({ color: '#a2a7ad', map: sleeveT, roughness: .95 }), hoodieD2: heroMat({ color: '#8b9096', roughness: .95 }),
    cotton: heroMat({ map: cTex(128, 128, (x, w, h) => knit(x, w, h, '#b3b7bb'), [3, 3]), roughness: .95 }),
    rib: heroMat({ map: cTex(64, 64, (x, w, h) => { x.fillStyle = '#a4a9af'; x.fillRect(0, 0, w, h); for (let i = 0; i < w; i += 4) { x.fillStyle = 'rgba(0,0,0,.18)'; x.fillRect(i, 0, 2, h); } }, [8, 1]), roughness: .95 }),
    jeans: heroMat({ map: denimT, bumpMap: denimT, bumpScale: .02, roughness: .9 }), jeansD: heroMat({ color: '#1d2538', roughness: .9 }),
    face: heroMat({ map: faceT, roughness: .62, emissive: '#2a1008', emissiveIntensity: .35 }),
    skin: heroMat({ map: skinT, roughness: .62, emissive: '#2a1008', emissiveIntensity: .35 }),
    lip: heroMat({ color: '#b86a66', roughness: .5 }), mouth: heroMat({ color: '#6e3434', roughness: .6 }),
    eyeW: heroMat({ color: '#f5f1ea', roughness: .25 }), iris: heroMat({ map: irisT, roughness: .2 }), lash: heroMat({ color: '#5a4630', roughness: .7 }),
    brow: heroMat({ color: '#c3a061', map: hairT, roughness: .7 }),
    hairMat: heroMat({ map: hairT, bumpMap: hairT, bumpScale: .02, vertexColors: true, roughness: .5, side: THREE.DoubleSide }),
    scalp: heroMat({ color: '#d2b673', map: hairT, roughness: .6 }),
    shoe: heroMat({ map: shoeT, roughness: .8 }), shoeW: heroMat({ map: rubberT, roughness: .7 }), lace: heroMat({ color: '#ecebe6', roughness: .8 }),
    metal: heroMat({ color: '#c7ccd2', roughness: .35, metalness: .6 }),
    nyText: new THREE.MeshStandardMaterial({ map: tex, transparent: true, alphaTest: .4, roughness: .8, side: THREE.FrontSide })
