        nrm.copy(a).sub(C0).normalize(); side.crossVectors(tan, nrm).normalize(); up.crossVectors(side, tan).normalize();
        const w = L.w * (1 - Math.pow(t, 1.15) * 0.97), th = w * 0.5;                        // tykke tuster med spisse tupper
        c.copy(L.col).multiplyScalar(0.8 + 0.28 * t);
