          const an = k / ring * Math.PI * 2, cx = Math.cos(an), cy = Math.sin(an);
          P.push(a.x + side.x * cx * w + up.x * cy * th, a.y + side.y * cx * w + up.y * cy * th, a.z + side.z * cx * w + up.z * cy * th);
          nn.set(side.x * cx + up.x * cy * 2.2, side.y * cx + up.y * cy * 2.2, side.z * cx + up.z * cy * 2.2).normalize(); N.push(nn.x, nn.y, nn.z);
