    if (weak) floatText(B.x, B.y - 260, 'Dobbel skade! 💥');
    if (B.st === 'sleep') { B.st = 'wake'; B.t = 1.2; sfx('roar'); }
    if (B.hp <= B.max / 2 && !B.raged) { B.raged = true; floatText(B.x, B.y - 280, 'Kongen blir rasende! 😡'); sfx('roar'); g.shake = 0.5; }
