  D.chests.forEach((c, i) => { const cm = C.chests[i]; cm.grp.visible = c.show; if (c.show) { cm.lid.rotation.x = turn(cm.lid.rotation.x, c.open ? -1.9 : 0, Math.min(1, dt * 5)); cm.sparkle.visible = !c.open; } });
