    const V = v._m; V.grp.visible = showSk; if (!showSk) continue;
    const amt2 = Math.min(1, v.spd / 110), sw2 = Math.sin(v.walk) * 0.6 * amt2;
    V.ang = turn(V.ang, v.face || 0, Math.min(1, dt * 10));
