    V.body.position.y = Math.abs(Math.sin(v.walk)) * 2 * amt2; V.torso.rotation.x = 0.12 * amt2;
    V.legs[0].hip.rotation.x = sw2 * .75; V.legs[1].hip.rotation.x = -sw2 * .75;
    V.legs[0].knee.rotation.x = Math.max(0, Math.sin(v.walk + 1.2)) * amt2; V.legs[1].knee.rotation.x = Math.max(0, -Math.sin(v.walk + 1.2)) * amt2;
    V.arms[0].sh.rotation.x = -sw2 * .9 + (v.awake ? 0 : 0.1 * Math.sin(time + v.hx)); V.arms[0].el.rotation.x = -0.4;
    const sl = v.atk > 0 ? v.atk / 0.5 : 0;
    V.arms[1].sh.rotation.x = sl > 0 ? 2.5 - (1 - sl) * 3.1 : (v.awake ? sw2 * .9 : -0.25); V.arms[1].el.rotation.x = -0.3;
