    const pts = []; for (let i = 0; i <= 14; i++) { const t = i / 14, r = t < .35 ? 13 * Math.sin(t / .35 * Math.PI / 2) : 13 * (1 + (t - .35) * .18); pts.push(new THREE.Vector2(Math.max(.01, r), 40 - 40 * t)); }
