  H.pumps.forEach((f, i) => f.material.opacity = .7 + Math.sin(time * 6 + i) * .2);
  H.mist.forEach((f, i) => { f.position.y = 12 + Math.sin(time * .5 + i) * 4; });
  H.wandG.visible = H.wandGlow.visible = !G.wand; H.wandG.rotation.y = time * 1.2; H.wandG.position.y = 52 + Math.sin(time * 2) * 3;
