  const neck = piv(body, 0, 12, 34); neck.add(mk(GEO.sphHi, bm, 12, 15, 15, 0, 8, 4)); neck.rotation.x = -0.25;
  const head = piv(neck, 0, 22, 8); head.scale.setScalar(1.3);
  head.add(mk(GEO.sphHi, bm, 13, 11, 18, 0, 4, 8), mk(GEO.sphHi, bm, 10, 8, 13, 0, 2, 22));               // skalle og snute
