  head.add(mk(GEO.sph, M.black, 1.4, 1, 1, 0, -4.4, 12.6));
  const beard = mk(GEO.cone, fur, 2.2, 8, 2.2, 0, -8, 9); beard.rotation.x = Math.PI; head.add(beard);   // skjegg
